# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.15.2/ankra-cli-darwin-arm64"
      sha256 "22aa3c98c0c872d942b8e6f7abc99aab6a36acc86eac122d90ebeb9911040420"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.15.2/ankra-cli-darwin-amd64"
      sha256 "45ae01ca8f4146cf4c914dbd217b561b2264a1548a25d63b00f61c30ba9918a8"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.15.2/ankra-cli-linux-arm64"
      sha256 "83587b6c1db1a9bc50f4d50a25b033920f15c83689a0d02534240e88ad8a49ab"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.15.2/ankra-cli-linux-amd64"
